# A level cut from the gis base map (map::compose): the apartment blocks in the north.
# Edit with: cargo run -- --campaign-editor gis --level 2

[properties]
name: The Blocks
stories: campaigns/gis/gis_02/gis_02_story.ron
loot: 1-3 per 40
escape_limit: 8
coins: 100
townsfolk: 12
base: campaigns/gis/world/world.map
region: 60, 20, 100, 90

[markers]
# marker: player | spawn | goal | at: <x, y in the base map's tiles>
marker: goal | at: 110, 63
marker: player | at: 112, 63
marker: spawn | at: 60, 40
marker: spawn | at: 105, 109
marker: spawn | at: 63, 20
marker: spawn | at: 88, 109

[placements]
# at: x, y | def: <def under assets/, e.g. defs/Barrel.ron> | rotation: <degrees, steps of 45>

[waves]
# enemy: <enemy def under assets/, omit for the built-in alien> | count: <n> | rate: <per minute>
count: 10 | rate: 10
enemy: defs/Bunny.ron | count: 14 | rate: 14
count: 24 | rate: 18
